options.afterRender:
// The panorama shown, in 360°, with Pannellum (loaded once from jsdelivr) on the picture the browser
// reads from the city. Query P is the panorama shown, M what is in sight from it (yaw and pitch: the
// picture has north in the middle and a level horizon, so a thing's place on it is its bearing and the
// angle up to it), N the steps to the next panoramas, Y the same spot in other years.
// A new panorama keeps the way the viewer looks. When the viewer stops turning or zooming it writes
// where it looks to $look and $fov (the map's wedge); a step writes $pano, a year $year.
const PANNELLUM = 'https://cdn.jsdelivr.net/npm/pannellum@2.5.6/build/';
const self = this;
context.element.style.height = '100%';
const box = context.element.querySelector('.pano-view');
const strip = context.element.querySelector('.pano-years');
const caption = context.element.querySelector('.pano-caption');
if (!box) {
  return;
}

const rowsOf = (refId) => {
  const frame = (context.panelData?.series ?? []).find((f) => f.refId === refId);
  if (!frame) {
    return [];
  }
  const n = frame.length ?? frame.fields[0]?.values.length ?? 0;
  return Array.from({ length: n }, (_, i) =>
    Object.fromEntries(frame.fields.map((f) => [f.name, f.values[i] ?? f.values.get?.(i)])),
  );
};
const setVars = (vars) => context.grafana.locationService.partial(vars, true);
const variable = (name) => context.grafana.replaceVariables('${' + name + '}');

// While a query runs again the panel can be handed a frame without its fields: only whole rows.
const shown = rowsOf('P').find((r) => r.pano_id && r.url_4000);
if (!shown) {
  if (!self.viewer) {
    box.textContent = 'No panorama of this year here.';
  }
  return;
}
const marks = rowsOf('M').filter((r) => r.kind && Number.isFinite(r.yaw) && Number.isFinite(r.pitch));
const steps = rowsOf('N').filter((r) => r.pano_id && Number.isFinite(r.yaw));
const years = rowsOf('Y').filter((r) => r.pano_id && r.year);

// Right after a step or a click, the panel draws once more with the rows of the panorama before:
// wait for the rows found for the panorama picked now.
if (shown.picked_id !== variable('pano') || String(shown.year) !== variable('year')) {
  return;
}
// The map rings the panorama picked: after a change of year, the one shown is the one picked.
if (shown.pano_id !== shown.picked_id) {
  setVars({ 'var-pano': shown.pano_id });
}

const load = () => {
  if (window.pannellum) {
    return Promise.resolve();
  }
  if (!window.__pannellumLoading) {
    window.__pannellumLoading = new Promise((resolve, reject) => {
      const css = document.createElement('link');
      css.rel = 'stylesheet';
      css.href = PANNELLUM + 'pannellum.css';
      document.head.appendChild(css);
      const script = document.createElement('script');
      script.src = PANNELLUM + 'pannellum.js';
      script.onload = resolve;
      script.onerror = () => {
        window.__pannellumLoading = null;
        reject(new Error('Pannellum did not load'));
      };
      document.head.appendChild(script);
    });
  }
  return window.__pannellumLoading;
};

const pin = (div, m) => {
  div.classList.add('pano-pin', 'pano-' + m.kind);
  div.dataset.distance = String(m.distance_m);
  const dot = document.createElement('i');
  const label = document.createElement('span');
  label.textContent = m.label;
  div.append(dot, label);
  div.title = `${m.detail} · ${Math.round(m.distance_m)} m away`;
};
const step = (div, s) => {
  div.classList.add('pano-step');
  div.title = `${Math.round(s.distance_m)} m on`;
};
const spots = [
  ...marks.map((m) => ({
    id: `m-${m.kind}-${m.id}`, pitch: m.pitch, yaw: m.yaw, cssClass: 'pano-spot',
    createTooltipFunc: pin, createTooltipArgs: m,
  })),
  ...steps.map((s) => ({
    id: `s-${s.pano_id}`, pitch: -24, yaw: s.yaw, cssClass: 'pano-spot',
    createTooltipFunc: step, createTooltipArgs: s,
    clickHandlerFunc: (_e, a) => setVars({ 'var-pano': a.pano_id }), clickHandlerArgs: s,
  })),
];
const scene = {
  type: 'equirectangular', panorama: shown.url_4000, crossOrigin: 'anonymous',
  haov: 360, vaov: 180, northOffset: 0, hotSpots: spots,
};
const key = `${shown.pano_id}|${marks.length}|${steps.length}`;

// Labels that would cover a nearer one's keep their dot only (the label shows on hover): checked
// whenever the view rests.
const declutter = () => {
  const pins = [...box.querySelectorAll('.pano-pin')].sort((a, b) => a.dataset.distance - b.dataset.distance);
  const kept = [];
  for (const p of pins) {
    p.classList.remove('crowded');
    const r = p.querySelector('span').getBoundingClientRect();
    if (!r.width) {
      continue;
    }
    if (kept.some((k) => r.left < k.right + 2 && r.right > k.left - 2 && r.top < k.bottom + 1 && r.bottom > k.top - 1)) {
      p.classList.add('crowded');
    } else {
      kept.push(r);
    }
  }
};

// Where the viewer looks, to the map, once it rests.
const publish = () => {
  setTimeout(declutter, 50);
  clearTimeout(self.lookTimer);
  self.lookTimer = setTimeout(() => {
    const v = self.viewer;
    if (!v) {
      return;
    }
    const look = String(Math.round(((v.getYaw() % 360) + 360) % 360));
    const fov = String(Math.round(v.getHfov()));
    if (look !== variable('look') || fov !== variable('fov')) {
      setVars({ 'var-look': look, 'var-fov': fov });
    }
  }, 400);
};

load()
  .then(() => {
    if (!self.viewer || self.box !== box || !box.isConnected || !box.querySelector('.pnlm-render-container')) {
      self.viewer?.destroy?.();
      self.box = box;
      box.replaceChildren();
      const look = Number(variable('look'));
      const fov = Number(variable('fov'));
      self.viewer = window.pannellum.viewer(box, {
        default: {
          firstScene: key, sceneFadeDuration: 500, autoLoad: true, compass: true,
          yaw: Number.isFinite(look) ? (look > 180 ? look - 360 : look) : 0, pitch: 4,
          hfov: Number.isFinite(fov) && fov >= 30 ? fov : 100, minHfov: 30, maxHfov: 120,
          showFullscreenCtrl: true, keyboardZoom: true, mouseZoom: true,
        },
        scenes: { [key]: scene },
      });
      for (const event of ['mouseup', 'touchend', 'zoomchange', 'animatefinished']) {
        self.viewer.on(event, publish);
      }
      self.viewer.on('load', () => setTimeout(declutter, 100));
      self.viewer.on('error', (message) => {
        caption.textContent = `The panorama did not load: ${message}`;
      });
      self.key = key;
    } else if (self.key !== key) {
      self.viewer.addScene(key, scene);
      self.viewer.loadScene(key, 'same', 'same', 'same');
      const old = self.key;
      self.key = key;
      setTimeout(() => {
        if (old !== self.key) {
          self.viewer?.removeScene?.(old);
        }
      }, 2000);
    }
  })
  .catch((e) => {
    box.textContent = e.message;
  });

// The same spot in other years.
strip.replaceChildren(
  ...years.map((y) => {
    const b = document.createElement('a');
    b.className = 'pano-year' + (Number(y.year) === Number(shown.year) ? ' picked' : '');
    b.textContent = String(y.year);
    b.title = `${y.taken_on}, ${Math.round(y.distance_m)} m from here`;
    b.onclick = () => setVars({ 'var-year': String(y.year), 'var-pano': y.pano_id });
    return b;
  }),
);
const away = shown.from_pick_m > 3 ? ` · ${Math.round(shown.from_pick_m)} m from the panorama picked` : '';
caption.textContent =
  `${shown.taken_on}${away} · ${marks.length} things in sight marked · Panorama: Gemeente Amsterdam, CC BY 4.0`;

options.styles:
.pano { display: flex; flex-direction: column; height: 100%; gap: 6px; }
.pano-view { flex: 1; min-height: 0; background: #000; border-radius: 2px; overflow: hidden; color: #9AA5B1; }
.pano-years { display: flex; flex-wrap: wrap; gap: 4px; }
.pano-year { font-size: 12px; padding: 1px 8px; border-radius: 10px; border: 1px solid #5A6672; color: #C7D0D9; cursor: pointer; text-decoration: none; }
.pano-year:hover { border-color: #FFA600; }
.pano-year.picked { background: #FFA600; border-color: #FFA600; color: #111; font-weight: 600; }
.pano-caption { font-size: 12px; line-height: 1.4; color: #9AA5B1; }
.pano-spot { width: 0; height: 0; }
.pano-pin i { position: absolute; left: -4px; top: -4px; width: 8px; height: 8px; border-radius: 50%; border: 1.5px solid #fff; box-shadow: 0 0 3px #000; }
.pano-pin span { position: absolute; left: 0; bottom: 8px; transform: translateX(-50%); white-space: nowrap; max-width: 220px; overflow: hidden; text-overflow: ellipsis; padding: 1px 7px; border-radius: 9px; font: 600 11px/1.4 Inter, Helvetica, Arial, sans-serif; color: #fff; background: rgba(17, 20, 26, 0.78); border: 1px solid rgba(255, 255, 255, 0.35); cursor: default; }
.pano-building i { background: #FFA600; }
.pano-building span { border-color: #FFA600; }
.pano-monument i { background: #F2495C; }
.pano-monument span { border-color: #F2495C; }
.pano-tree i { background: #5BBF73; }
.pano-tree span { border-color: #5BBF73; font-weight: 400; font-style: italic; }
.pano-pin.crowded span { visibility: hidden; }
.pano-pin:hover { z-index: 10; }
.pano-pin:hover span { visibility: visible; max-width: none; background: rgba(17, 20, 26, 0.95); }
.pano-step { width: 34px; height: 34px; border-radius: 50%; background: rgba(255, 255, 255, 0.82); box-shadow: 0 0 6px rgba(0, 0, 0, 0.6); cursor: pointer; }
.pano-step::after { content: ''; position: absolute; left: 10px; top: 5px; border: 7px solid transparent; border-bottom: 11px solid #111; pointer-events: none; }
.pano-step:hover { background: #FFA600; }
